"""Attach discovered151 project dependencies to the scoring admission and source freeze without changing generated bytes."""
from pathlib import Path
import sys,time
ROOT=Path(__file__).resolve().parents[1];A=ROOT/'analysis';sys.path[:0]=[str(ROOT),str(A)]
from run_dependency_queue_v3_20261006 import read,sha,create
META=A/'RFFSparse151_source_closure_receiver_runtime_v1_20261009.json'
CLOSURE=A/'RFFSparse151_project_source_closure_v1_20261009.json'
DRIVERS={
    'verify_RFFSparse59_round151_sources_v1_20261009.py':'verify_RFFSparse59_round151_sources_v2_20261009.py',
    'publish_RFFSparse59_evidence_v2_20261009.py':'publish_RFFSparse59_evidence_v3_20261009.py',
    'dispatch_RFFSparse151_complete_pipeline_v1_20261009.py':'dispatch_RFFSparse151_complete_pipeline_v2_20261009.py'}

def prepare():
    closure=read(CLOSURE)
    assert closure['status']=='passed_actual_project_import_literal_backend_and_generated_source_dependency_closure_before_quality'
    for path,digest in closure['input_sha256'].items():assert sha(path)==digest,path
    files=[Path(__file__),CLOSURE,*(A/n for n in DRIVERS),*(A/n for n in DRIVERS.values())]
    for p in files:
        if p.suffix=='.py':compile(p.read_text(encoding='utf8'),str(p),'exec')
    create(META,{'status':'frozen151_project_dependency_closure_receivers_before_quality_source_admission','at_local':time.strftime('%Y-%m-%dT%H:%M:%S'),
        'input_sha256':{**closure['input_sha256'],**{str(p):sha(p) for p in files}},'project_source_count':closure['project_source_count'],
        'original32_generated_source_bytes_and440_graph_controls_unchanged':True,'new_quality_scores':0,'new_future_inference':0,'new_native_fits':0,'test_labels_read':False})

def execute(name,*args):
    meta=read(META)
    for path,digest in meta['input_sha256'].items():assert sha(path)==digest,path
    import prepare_RFFSparse59_round151_sources_v1_20261009 as generator
    previous=generator.source_paths
    generator.source_paths=lambda:list(dict.fromkeys([*previous(),*(Path(p) for p in meta['input_sha256']),META]))
    source=(A/name).read_text(encoding='utf8')
    if name.startswith('dispatch_'):
        source=source.replace('verify_RFFSparse59_round151_sources_v1_20261009.py',DRIVERS['verify_RFFSparse59_round151_sources_v1_20261009.py'])
        source=source.replace('publish_RFFSparse59_evidence_v2_20261009.py',DRIVERS['publish_RFFSparse59_evidence_v2_20261009.py'])
        source=source.replace('RFFSparse151_complete_hidden_launches_v1_20261009','RFFSparse151_complete_hidden_launches_v2_20261009')
    ns={'__name__':'actual151_project_source_closure_bound_runtime','__file__':str(A/DRIVERS[name])}
    exec(compile(source,str(A/name),'exec'),ns)
    if name.startswith('verify_'):
        before=ns['create']
        def bound_create(path,value):
            if Path(path).name in ('RFFSparse59_actual_controls_index_v1_20261009.json','RFFSparse59_round151_source_admission_v1_20261009.json'):
                value={**value,'input_sha256':{**value['input_sha256'],**meta['input_sha256'],str(META):sha(META)},'actual_project_source_import_closure_pinned':True,'project_source_count':meta['project_source_count']}
            return before(path,value)
        ns['create']=bound_create
    ns['main'](*args)

if __name__=='__main__':prepare()
